import { Text } from "@chakra-ui/react";
import { type NodeProps, Handle, Position } from "reactflow";
import type { FlowNodeStart } from "../../types";
import { extractNodeLabel } from "../../utils";

export const StartAloneNode = (props: NodeProps<FlowNodeStart>) => {
  const { data, isConnectable, sourcePosition, selected } = props;

  const sx = {
    bg: "cyan.solid",
    color: "cyan.contrast",
    borderRadius: "full",
    border: "none",
    borderColor: "transparent",
    boxShadow: "tooltip",
    px: "6",
    py: "2",
    pointerEvents: "all",
    height: "8",
  };

  return (
    <>
      <Text textStyle="xs" tabIndex={0} css={sx} data-testid={selected ? "node-selected" : "node"}>
        {extractNodeLabel(data)}
      </Text>
      <Handle
        type="source"
        position={sourcePosition || Position.Bottom}
        isConnectable={isConnectable}
      />
    </>
  );
};
